DROP TYPE IF EXISTS member_lcr_status CASCADE;
CREATE TYPE member_lcr_status AS ENUM ('active', 'active_ready_to_serve', 'active_serving', 'active_hold', 'less_active', 'not_active_contact_ok', 'unknown', 'do_not_contact', 'check_for_moved_out', 'moved_out', 'deceased', 'on_mission', 'name_removed', 'do_not_contact_hostile', 'name_removal_requested');

DROP TYPE IF EXISTS sensitivity_level CASCADE;
