DROP TYPE IF EXISTS task_priority CASCADE;
CREATE TYPE task_priority AS ENUM ('Low', 'Medium', 'High', 'Urgent');

DROP TYPE IF EXISTS task_status CASCADE;
CREATE TYPE task_status AS ENUM ('Not Started', 'In Progress', 'Completed', 'Abandoned');

DROP TYPE IF EXISTS user_role CASCADE;
CREATE TYPE user_role AS ENUM ('bishop', 'bishopric', 'exec_sec', 'ward_clerk', 'rs_president', 'eq_president', 'org_president', 'ward_council');

DROP TYPE IF EXISTS visit_type CASCADE;
