INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('0619543a-63d9-4a0c-8b97-c9838ad572c0', '52fb1287-337b-48f4-a11e-5189077f3b1e', '87709d79-a29f-40c4-a61e-0133f6b77145', 'Calling Interview: Ward Activities Co-Chair: Reynolds, Tricia', '2026-06-07'::date, 'Interview'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', 'Dave Houssian', 'Both Spencer and Trish were excited to serve as activities chairpeople. They will not be in charge of the beach day. ', NULL, FALSE, NULL, 'Not Started'::task_status, NULL, NULL, NULL, 'bishopric'::sensitivity_level, FALSE, NULL, '2026-06-07T19:25:36.445343+00:00'::timestamptz, '2026-06-07T19:25:36.445343+00:00'::timestamptz, NULL, 5, NULL);
INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('06a23a3c-07af-4b4d-9675-693181dc5520', 'b90d1d4c-e7ff-446e-95d7-4c17dec282c9', '4e3eda7d-57da-446f-8a36-6f11f9ab5eca', 'Calling Nicole Jellings as Primary President ', '2026-07-30'::date, 'In-Person Meeting'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', NULL, NULL, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, 'bishop_only'::sensitivity_level, TRUE, '2409a4dd-fb10-425d-9d18-4cd0787439d8', '2026-07-31T00:00:01.695857+00:00'::timestamptz, '2026-07-31T00:00:01.695857+00:00'::timestamptz, NULL, 1, 'Jellings, Nicole, Jellings, Don');
INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('0e56f6bb-a6a1-4e30-ac69-d4a1defed005', 'd013ecad-bbde-47a2-8a69-c334d80820d8', '5631c714-89df-4783-bbad-c3cccf048d75', 'All grades over 80, no summer school, plans for summer discussed, check-in ', '2026-06-07'::date, 'In-Person Meeting'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', NULL, 'Dave Houssian and Sawyer Ramsey discussed Sawyer''s improved academic performance, now above 80, avoiding summer school. Sawyer shared updates on his mother''s urgent eye surgery, scheduled at Baskin Palmer in Miami, with a planned absence from July 10 to 31. They also discussed Sawyer''s need to complete 56 service hours, with 27 remaining. Dave suggested church cleaning tasks and reaching out to local service programs. Sawyer mentioned potential help from his grandparents and the possibility of using Medicare for non-medical rides. They concluded with a prayer for Sawyer''s continued success and his mother''s recovery.', NULL, FALSE, NULL, 'Not Started'::task_status, NULL, NULL, NULL, 'bishopric'::sensitivity_level, FALSE, NULL, '2026-06-07T22:25:23.943837+00:00'::timestamptz, '2026-06-07T22:25:23.943837+00:00'::timestamptz, NULL, 5, 'Ramsey, Sawyer Michael');
INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('109a98db-f7ba-43fa-99b6-364665343fe3', '445049f1-e7b9-4ac1-ad59-d7c34e54cd72', '8348dcee-0392-45d7-a38c-f6a7e54d7757', 'Christina Robinson, interview in preparation for patriarchal blessing ', '2026-04-26'::date, 'In-Person Meeting'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', NULL, 'Visited with Christina about getting her patriarchal blessing. Discussed what a blessing is, what to expect, and how to continue preparing for it. Sister Nicole Jellings joined us for the conversation. Deliver to her later in the evening, after getting home, a link to the "Preparing for Your Patriarchal Blessing" Google document that is linked here: https://docs.google.com/document/d/10cWMPeEr4UlExjaeNZmOVQfLhK0C7hox8ZKcmeDy76A/edit?usp=sharing
INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('2797a766-a8d1-4d23-8b87-39d3e8b3ecab', 'b5bfcde4-e843-479a-868b-ea56a97ed0b1', 'db70b5da-2906-4e04-8c82-9b14b7a31b15', 'Temple recommend renewal and catch up ', '2026-05-03'::date, 'In-Person Meeting'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', NULL, 'You and Claudette talked about her unexpected $160 raffle win, using it as a springboard to reflect on the power of wishes, words, and positive spiritual focus. You connected that experience to ideas like The Secret / law of attraction, then reframed it in gospel terms—faith, prayer, “ask and it shall be given,” and focusing spiritually on righteous desires. Claudette shared her testimony of God, Christ, and the Holy Ghost, including how the Holy Ghost has guided her despite a difficult relationship with her earthly father. She bore testimony of the Atonement, temple teachings, and her patriarchal blessing—including a line about seeing the fulfillment of the last days—which shapes her sense that we are nearing the end times but that she feels spiritually ready. You both briefly discussed deception in the last days, modern issues like AI and land purchases by the Church, and then transitioned toward the formal temple recommend questions.', NULL, FALSE, NULL, 'Not Started'::task_status, NULL, NULL, NULL, 'bishop_only'::sensitivity_level, TRUE, '2409a4dd-fb10-425d-9d18-4cd0787439d8', '2026-05-07T00:26:24.376696+00:00'::timestamptz, '2026-05-07T00:26:24.376696+00:00'::timestamptz, NULL, 5, 'Poirier, Claudette');
INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('27dae3f5-1fb2-49ad-8bbd-da539c441474', '52fb1287-337b-48f4-a11e-5189077f3b1e', '87709d79-a29f-40c4-a61e-0133f6b77145', 'Calling Interview: Ward Activities Co-Chair: Reynolds, Tricia', '2026-06-07'::date, 'Interview'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', 'Dave Houssian', 'Both Spencer and Trish were excited to serve as activities chairpeople. They will not be in charge of the beach day. ', NULL, FALSE, NULL, 'Not Started'::task_status, NULL, NULL, NULL, 'bishopric'::sensitivity_level, FALSE, NULL, '2026-06-07T19:25:34.870815+00:00'::timestamptz, '2026-06-07T19:25:34.870815+00:00'::timestamptz, NULL, 5, NULL);
INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('28c1933c-b58c-4c70-96de-52c4afbf99fe', 'd013ecad-bbde-47a2-8a69-c334d80820d8', '5631c714-89df-4783-bbad-c3cccf048d75', 'Call and text with Sawyer about argument with Mom. He chose to Baker Act himself for a week.', '2026-05-07'::date, 'Phone Call'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', NULL, 'Sawyer and Gina got into a tiff. She started to call the police. When the police arrived, he decided to bake, wrapped himself, instead of going to jail. He is in the Land O''Lakes Bay Care Facility at 21808 state road 54, Land O''Lakes. 
INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('2e4f6dec-9e61-4f1a-a36f-1bebcb2cbe6a', 'b90d1d4c-e7ff-446e-95d7-4c17dec282c9', '8adb3182-788e-481b-84b5-38b6256ef6de', 'Annabell Lee Jones baptismal interview', '2026-07-30'::date, 'In-Person Meeting'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', NULL, 'Annabel Lee Jones is preparing for her baptism and is interviewed by Dave Houssian. Annabel explains her desire to get baptized to follow Jesus'' example and become a disciple of Christ. Dave explains the significance of baptism, the covenant path, and the sacrament. Annabel''s family, including her second cousin from Ohio who will baptize her, and her uncle who will confirm her, are involved. Annabel plans to present Girl Scout posters as her talent. Annabel enjoys swimming, reading, and art. Dave testifies to the truth of the Church and the gospel, and Annabel expresses her readiness for baptism.
INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('329185d1-6b94-41d0-89d3-aa350e2fcf97', '9aa88777-1586-429e-8e52-ccc602d0560c', '3a57a164-2d52-401e-bd4e-758eb6053bbf', 'President Henry, Hayden, Bishop conversation about advancing to the Melchizedek priesthood & considering a mission', '2026-04-21'::date, 'In-Person Meeting'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', NULL, 'Conversation around Hayden''s spiritual development and future steps in the church. Dave Houssian and Pres. Ryan Henry discuss Hayden''s progress, including his baptism in October and potential advancement to the Melchizedek priesthood. They emphasize the importance of covenants with God and the readiness to make promises. Hayden expresses a desire to focus on his career before considering a mission. Dave Houssian reassures him about financial support for a mission, should he deside to go. The discussion also touches on the benefits and challenges of serving a mission, including potential career disruptions. The meeting concludes with a prayer for guidance and support.', NULL, TRUE, 'Meet with Bishop Houssian around the May 15–16 State Conference period to discuss readiness for Melchizedek Priesthood ordination and clarify any questions about the covenant.', 'Not Started'::task_status, NULL, NULL, NULL, 'ward_council'::sensitivity_level, FALSE, '2409a4dd-fb10-425d-9d18-4cd0787439d8', '2026-04-22T00:36:49.305475+00:00'::timestamptz, '2026-04-22T00:36:49.305475+00:00'::timestamptz, NULL, 5, 'Clement, Hayden James');
