INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('4664820a-5db0-41b9-bd63-520007400420', NULL, '8c0d0fcb-cbbc-4997-b4e9-eb74b7c9b371', 'Working to get clearance to be re-baptized', '2026-04-21'::date, 'Phone Call'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', NULL, 'John Michael Carmichael is contemplating baptism but is uncertain about his belief in the church president as a true prophet. Dave Houssian shares his personal experience of witnessing the Prophet''s presence, emphasizing the spiritual confirmation he felt. John recounts his past church involvement, including leaving the church at age 21 and his inability to find his records despite providing all necessary details. Dave assures John that the church will investigate further and, if necessary, proceed with his baptism. John''s birthplace is confirmed as St. Pete, Florida, and he is asked to provide additional information to facilitate the process.', NULL, FALSE, NULL, NULL, NULL, NULL, NULL, 'bishop_only'::sensitivity_level, TRUE, NULL, '2026-04-22T00:17:50.542138+00:00'::timestamptz, '2026-04-22T00:17:50.542138+00:00'::timestamptz, 'https://otter.ai/u/tHUFO6y-ndHfLyEJlBsbJc153PM?utm_source=copy_url', 1, 'John Carmichael');
INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('51a5e1fe-44c1-46f1-8a23-cfa136fc67db', '021ff764-8a3c-4d8b-9a46-89831ef8afdc', '5fb8b65f-75f7-48ab-92fb-1b00d2ddc19f', 'Nic Temple Renewal and Check-in ', '2026-05-08'::date, 'In-Person Meeting'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', NULL, 'Nic and Kristen are trying to work through things to stay together. It is looking positive right now. The six weeks of trading back and forth between Tampa and Missouri have yielded positive results. 
INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('6867c625-43fc-4a4e-9922-e4c9c31aff0e', '88ed4b8c-32dd-4aac-8aab-8e1d6b8d4a87', 'f911dd24-21f0-4d91-8306-a5d73066362e', 'Check in with Romeo and Temple Recommend Renewal ', '2026-06-07'::date, 'In-Person Meeting'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', NULL, 'Romeo discussed his personal growth, noting improvements in his behavior and responsibilities. Dave Houssian inquired about Romeo''s testimony of God, Jesus Christ, and the Holy Ghost, emphasizing the importance of understanding the atonement and the restoration of the gospel. They also discussed the unique aspects of their faith, including the priesthood authority and the role of prophets. Romeo affirmed his commitment to Church teachings, including moral cleanliness, the law of chastity, and tithing. He expressed readiness to enter the temple and participate in ordinances, despite acknowledging his imperfections. The conversation concluded with plans for Romeo''s summer activities and camp.
INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('68788fe8-4cfc-477c-b071-bc3dc346fad2', '52fb1287-337b-48f4-a11e-5189077f3b1e', '71de8729-6d50-48c8-8f8d-b7716e7a653a', 'Spencer and Tricia Reynolds accepted calling forward activities leaders. ', '2026-06-07'::date, 'In-Person Meeting'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', NULL, 'Dave Houssian discussed the formation of a ward activity chairperson couple, noting previous successful collaborations and the involvement of the ward council. He proposed creating a stake activities committee for better coordination and suggested combining ward and stake events, such as adult dances and youth activities. The group also discussed the need for better communication and promotion within the stake.  Travel plans for October were also reviewed, ensuring no conflicts with ward activities.', NULL, FALSE, NULL, 'Not Started'::task_status, NULL, NULL, NULL, 'bishopric'::sensitivity_level, FALSE, NULL, '2026-06-07T22:22:57.602407+00:00'::timestamptz, '2026-06-07T22:22:57.602407+00:00'::timestamptz, NULL, 5, 'Reynolds, Spencer, Reynolds, Tricia');
INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('6fef3629-e3ca-4680-8cdd-02fdab1fb683', 'b90d1d4c-e7ff-446e-95d7-4c17dec282c9', '8adb3182-788e-481b-84b5-38b6256ef6de', 'Kooper Mission Paper Initiation, and check in on past issues ', '2026-06-07'::date, 'In-Person Meeting'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', NULL, 'Dave Houssian and Kooper discussed upcoming mission to BYU and his preparations. Koopershared his excitement about meeting new people and overcoming social awkwardness. Dave emphasized the importance of living gospel standards, particularly the law of chastity, and asked about Koopwer''s past transgressions and current habits. They also discussed the need for medical and dental checks, and the process of transferring records to a YSA ward at BYU. Dave advised Kooper to focus on his triggers, build better habits, and prepare spiritually for his mission.
