INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('7d684077-5278-4473-932a-bce6ec356191', '28dd781c-b084-416b-9214-e1607d1f8179', 'c60aadd1-066f-49a6-a3c1-0f1ab402e586', 'Working toward Patriarchal Blessing and Temple Attendance in August ', '2026-06-07'::date, 'In-Person Meeting'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', NULL, 'Zackery Mendoza discussed his struggles with substance abuse and his recent spiritual awakening, including daily scripture reading and prayer. Dave Houssian offered support, sharing his own experiences with addiction and emphasizing the importance of faith and repentance. They discussed setting goals, such as obtaining a patriarchal blessing and attending the temple by August 8th. Dave suggested attending a recovery class and encouraged Zackery to focus on self-improvement and service. Lauren expressed concerns about her brother and father''s similar struggles. Both received blessings, emphasizing discernment, strength, and forgiveness. Dave emphasized the power of service and the importance of turning to the Lord. - https://otter.ai/u/Z-eOfbkkWQmlrv8Fvo28Rib8cbA?utm_source=copy_url', NULL, FALSE, NULL, 'Not Started'::task_status, NULL, NULL, NULL, 'bishop_only'::sensitivity_level, TRUE, '2409a4dd-fb10-425d-9d18-4cd0787439d8', '2026-06-07T22:20:52.062495+00:00'::timestamptz, '2026-06-07T22:20:52.062495+00:00'::timestamptz, NULL, 5, 'Mendoza, Zackery, Mendoza, Lauryn');
INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('804c4631-2dd5-4865-80d5-b9839ee14eb5', 'a782138d-7fcf-480e-8749-b86655d6405e', '8c0d0fcb-cbbc-4997-b4e9-eb74b7c9b371', 'John preparing for a Melchizedek Priesthood Advancement ', '2026-05-03'::date, 'In-Person Meeting'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', NULL, 'Your conversation with John focused on his readiness to advance in the priesthood from Aaronic to Melchizedek (elder). You taught that the priesthood is God’s authority delegated to man, emphasizing how the Aaronic priesthood administers outward ordinances (like baptism and the sacrament) while the Melchizedek priesthood brings higher spiritual responsibility, personal revelation, and stewardship in the home. You walked him through Doctrine and Covenants 20, explaining the duties of priests, teachers, and deacons, and highlighted that advancement raises expectations for personal worthiness and repentance. You then conducted a full temple recommend–style interview, confirming his faith in Christ, acceptance of restored priesthood authority, commitment to live church standards (including tithing going forward), and his own sense of worthiness. You told John you see no reason to delay his advancement, will recommend him to the stake president for ordination to the office of elder, issue him a limited-use recommend now, and encouraged him to prepare for the temple endowment and to continue leading his family with patience and love, especially regarding his wife’s gradual spiritual journey.', NULL, FALSE, NULL, 'Not Started'::task_status, NULL, NULL, NULL, 'bishop_only'::sensitivity_level, TRUE, '2409a4dd-fb10-425d-9d18-4cd0787439d8', '2026-05-07T00:27:48.038928+00:00'::timestamptz, '2026-05-07T00:27:48.038928+00:00'::timestamptz, NULL, 5, 'Carmichael, John');
