INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('bdf87a24-bb26-4066-9b42-c06fefa93897', '31101e25-4bd7-463b-b648-1579688a241c', '1ecf03ba-2741-437b-8d20-8ba247014284', 'Marital trust broken on Facebook discussion', '2026-04-09'::date, 'In-Person Meeting'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', NULL, NULL, NULL, TRUE, 'Check with Justin if he wants to get together with Karina and I for a follow up visit or just wants to follow up with me by himself', 'Not Started'::task_status, NULL, NULL, NULL, 'bishop_only'::sensitivity_level, TRUE, '2409a4dd-fb10-425d-9d18-4cd0787439d8', '2026-04-10T03:13:21.535996+00:00'::timestamptz, '2026-04-10T03:13:21.535996+00:00'::timestamptz, NULL, 1, NULL);
INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('c32b60f5-b42c-42b6-a723-7d2c1198e18d', '021ff764-8a3c-4d8b-9a46-89831ef8afdc', '5fb8b65f-75f7-48ab-92fb-1b00d2ddc19f', 'Loss of hope, difficult marital decisions coming soon', '2026-04-08'::date, 'In-Person Meeting'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', NULL, 'Nick has lost hope and feels beat down / burnt out. Making decisions around separating from Kristen. Fasting about his next steps this fast Sunday, not taking the sacrament this Sunday as part of his personal repentance. ', NULL, FALSE, NULL, NULL, NULL, NULL, NULL, 'bishop_only'::sensitivity_level, TRUE, '2409a4dd-fb10-425d-9d18-4cd0787439d8', '2026-04-09T09:13:43.764548+00:00'::timestamptz, '2026-04-09T09:13:43.764548+00:00'::timestamptz, 'https://otter.ai/u/CdSYJXSIW-gPfotsL-R5ju1KFwQ?utm_source=copy_url', 1, NULL);
INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('d1461d0b-6638-4644-842b-7a241804c5b0', 'd630118a-8c50-4ac4-9b84-4b18e645c6cd', 'bfa8ec19-f1d9-42d0-853a-a235db5c338d', 'Serena moving to Lutz in the next couple of months', '2026-04-19'::date, 'In-Person Meeting'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', NULL, 'Serena discussed her upcoming move to North Carolina, helping her parents pack and say goodbye to their old branch. She shared a vivid dream about Moses and prophets, which she believes was a spiritual experience. Serena also recounted seeing her husband, Kevin, in a deteriorated state that she did not recognize him at a grocery store, highlighting his severe health decline and financial struggles. She mentioned renovating a house she is living in for free from well-to-do friends and plans to move in within a few months. Serena also talked about her friendship with a neighbor near the new house and her commitment to maintaining her covenants, including the laws of Chastity, Word of Wisdom, and Tithing.', NULL, FALSE, NULL, 'Not Started'::task_status, NULL, NULL, NULL, 'bishopric'::sensitivity_level, FALSE, NULL, '2026-04-22T00:30:53.019773+00:00'::timestamptz, '2026-04-22T00:30:53.019773+00:00'::timestamptz, NULL, 5, 'Gay, Serena Cathleen');
INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('dc9d39bd-9b13-42b5-b25f-80377ac258bb', '021ff764-8a3c-4d8b-9a46-89831ef8afdc', '5fb8b65f-75f7-48ab-92fb-1b00d2ddc19f', 'Pres Henry Guidance', '2026-04-09'::date, 'Phone Call'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', NULL, 'Spoke to President Henri about the conversation with Nick last night, Wednesday, April 8. He will visit with Nick and offer to visit with Kristen if Nick thinks it''s a good thing. I suggested that he not visit with them as a couple because it will turn into a complaint session.', NULL, FALSE, NULL, NULL, NULL, NULL, NULL, 'bishop_only'::sensitivity_level, TRUE, NULL, '2026-04-10T02:59:13.227166+00:00'::timestamptz, '2026-04-10T02:59:13.227166+00:00'::timestamptz, NULL, 1, NULL);
INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('e480fb25-5803-4751-902d-2c2203eb542a', NULL, 'e778768c-f030-435e-bdec-9e32e0d2bb22', 'Follow-up visit with Kayla as she continues to work towards getting to the temple ', '2026-04-26'::date, 'In-Person Meeting'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', NULL, 'Kayla continues to struggle with confidence, depression, finding purpose, and the other worthiness issues we have discussed previously (masturbation).  Encouraging her to continue praying and working on things. Asking her to focus on making herself more independent spiritually, financially, and emotionally encouraging her to be in places where positivity or peace reigns. This may mean getting out of the house and going to places like the library, but getting away from those who want to be disruptive, like her Aunt Rachel, is important. ', NULL, FALSE, NULL, 'Not Started'::task_status, NULL, NULL, NULL, 'bishop_only'::sensitivity_level, TRUE, '2409a4dd-fb10-425d-9d18-4cd0787439d8', '2026-04-27T02:41:29.509398+00:00'::timestamptz, '2026-04-27T02:41:29.509398+00:00'::timestamptz, NULL, 5, 'Getty, Kayla');
INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('f14860e2-e6f7-4ccf-ab7d-2d87874e389c', NULL, '5631c714-89df-4783-bbad-c3cccf048d75', 'Driving to youth together.', '2026-04-08'::date, 'In-Person Meeting'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', NULL, 'School is going better, grades though still rough are coming up. No complaining about Gina. Still focused on just the worldly things. But at the same time he get frustrated with kids at this alternative school that are making terrible choices, and he can''t understand why they would want to push that on people like him', NULL, FALSE, NULL, NULL, NULL, NULL, NULL, 'bishopric'::sensitivity_level, FALSE, NULL, '2026-04-09T09:19:39.080131+00:00'::timestamptz, '2026-04-09T09:19:39.080131+00:00'::timestamptz, NULL, 3, NULL);
INSERT INTO public.visits ("id", "household_id", "member_id", "visit_title", "visit_date", "visit_type", "recorded_by", "recorded_by_name", "summary", "needs_identified", "follow_up_required", "follow_up_description", "follow_up_status", "assigned_to", "assigned_to_name", "assignment_org", "sensitivity", "private_to_bishop", "private_owner", "created_at", "updated_at", "call_recording_url", "permission_level", "member_names") VALUES ('fe9171a7-9d6b-4077-9e0e-1c75f8e1dbba', NULL, 'de6e90fc-1555-494e-a293-0e7f44daee6b', 'Vivian Kropic Private Conversation', '2026-07-12'::date, 'In-Person Meeting'::visit_type, '2409a4dd-fb10-425d-9d18-4cd0787439d8', NULL, 'Vivian discussed her recent challenges, including her divorce finalized in April and a subsequent bad decision in May. She met with President Henry and is undergoing a repentance process. Dave Houssian offered support, emphasizing forgiveness and the importance of her journey. Vivian shared her exhaustion from balancing work, school, and raising kids. She works with victims of felony domestic battery and finds purpose in her job. Dave offered practical help, including a food order. Vivian expressed gratitude for her parents'' support and the church community. The meeting concluded with a prayer for strength and peace.', NULL, FALSE, NULL, NULL, NULL, NULL, NULL, 'ward_council'::sensitivity_level, FALSE, '2409a4dd-fb10-425d-9d18-4cd0787439d8', '2026-07-30T23:52:04.265439+00:00'::timestamptz, '2026-07-30T23:52:04.265439+00:00'::timestamptz, 'https://otter.ai/u/OAuhivY3ngeQhGzt64bumXqPkNs?utm_source=copy_url', 5, 'Kropik, Vivian M.');
